// Baut den Kandidaten-Text fuer den Prompt und die gueltige ID-Liste (Anforderung 4).
const body = $input.first().json.body;
const meldung = body.meldung;
const kandidaten = body.kandidaten;

const zeilen = kandidaten.map(k => {
  const kern = k.kernaussage ? k.kernaussage : '(keine Kernaussage)';
  const beispiele = k.beispiele.join(' / ');
  return 'ID ' + k.geruecht_id + ': ' + kern + ' Beispiele: ' + beispiele;
});

return [{ json: {
  meldung_id: meldung.meldung_id,
  meldung_text: meldung.text,
  kandidaten_ids: kandidaten.map(k => k.geruecht_id),
  kandidaten_text: zeilen.join('\n')
} }];

// Anforderung 4: erfundene oder falsche ID wird auf null gesetzt, mit Vermerk in der Begruendung.
const gueltigeIds = $('Kandidaten aufbereiten').first().json.kandidaten_ids;
const r = $input.first().json.output ?? $input.first().json;

let geruechtId = r.geruecht_id;
let begruendung = String(r.begruendung ?? '').slice(0, 1000);

if (geruechtId !== null && geruechtId !== undefined && !gueltigeIds.includes(Number(geruechtId))) {
  begruendung = begruendung + ' (Hinweis: vom Modell genannte ID ' + geruechtId + ' war nicht unter den Kandidaten, auf null gesetzt.)';
  geruechtId = null;
} else if (geruechtId !== null && geruechtId !== undefined) {
  geruechtId = Number(geruechtId);
}

return [{ json: { geruecht_id: geruechtId, begruendung } }];
